def get_user_all_memories(self, user_id: str):
    """获取用户的所有记忆"""
    # Chroma 的 get() 方法可以通过 where 过滤
    results = self.collection.get(
        where={"user_id": user_id}
    )
    memories = []
    for i, doc in enumerate(results['documents']):
        memory = {
            'id': results['ids'][i],
            'text': doc,
            'metadata': results['metadatas'][i]
        }
        memories.append(memory)
    return memories

def clear_user_memories(self, user_id: str):
    """清空用户的所有记忆"""
    # 先获取该用户的所有记忆ID
    results = self.collection.get(
        where={"user_id": user_id}
    )
    if results['ids']:
        self.collection.delete(ids=results['ids'])
        print(f"✓ 已清空用户 {user_id} 的 {len(results['ids'])} 条记忆")
    else:
        print(f"用户 {user_id} 没有记忆")

def get_memory_stats(self):
    """获取记忆统计信息"""
    # 获取所有记忆
    all_data = self.collection.get()
    total_count = len(all_data['ids'])
    # 按用户统计
    user_counts = {}
    for metadata in all_data['metadatas']:
        user_id = metadata.get('user_id', 'unknown')
        user_counts[user_id] = user_counts.get(user_id, 0) + 1
    return {
        "total_memories": total_count,
        "user_count": len(user_counts),
        "memories_by_user": user_counts
    }

def safe_save_memory(self, user_id: str, text: str, metadata: dict = None):
    """安全保存记忆（带错误处理）"""
    try:
        return self.save_memory(user_id, text, metadata)
    except Exception as e:
        print(f"✗ 保存记忆失败: {e}")
        # 记录日志或回退策略
        return None
